    $data=[(int)($_POST['category_id']??0)?:null,(int)($_POST['city_id']??0)?:null,(int)($_POST['business_id']??0)?:null,$postType,$lang,$titleEn?:null,$titleUr?:null,$slug,trim((string)($_POST['excerpt_en']??''))?:null,trim((string)($_POST['excerpt_ur']??''))?:null,trim((string)($_POST['body_en']??''))?:null,trim((string)($_POST['body_ur']??''))?:null,$image?:null,trim((string)($_POST['video_url']??''))?:null,trim((string)($_POST['source_name']??''))?:null,trim((string)($_POST['source_url']??''))?:null,trim((string)($_POST['reporter_name']??''))?:null,isset($_POST['is_breaking'])?1:0,isset($_POST['is_featured'])?1:0,$status,$published,$uid?:null];
    if($id)db()->prepare("UPDATE news_posts SET category_id=?,city_id=?,business_id=?,post_type=?,language=?,title_en=?,title_ur=?,slug=?,excerpt_en=?,excerpt_ur=?,body_en=?,body_ur=?,image_url=?,video_url=?,source_name=?,source_url=?,reporter_name=?,is_breaking=?,is_featured=?,status=?,published_at=?,created_by=COALESCE(created_by,?) WHERE id=?")->execute(array_merge($data,[$id]));
    else db()->prepare("INSERT INTO news_posts(category_id,city_id,business_id,post_type,language,title_en,title_ur,slug,excerpt_en,excerpt_ur,body_en,body_ur,image_url,video_url,source_name,source_url,reporter_name,is_breaking,is_featured,status,published_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute($data);
    $msg='News post saved.';
  } elseif($action==='delete_post'){db()->prepare("DELETE FROM news_posts WHERE id=?")->execute([(int)$_POST['id']]);$msg='News post deleted.';}
  elseif($action==='duplicate_post'){$id=(int)$_POST['id'];$q=db()->prepare("SELECT * FROM news_posts WHERE id=?");$q->execute([$id]);$r=$q->fetch();if(!$r)throw new RuntimeException('Post not found.');unset($r['id']);$r['slug']=news_slug(($r['title_en']?:$r['title_ur']).'-copy');$r['status']='draft';$r['is_breaking']=0;$r['published_at']=null;$cols=array_keys($r);$sql="INSERT INTO news_posts(`".implode('`,`',$cols)."`) VALUES(".implode(',',array_fill(0,count($cols),'?')).")";db()->prepare($sql)->execute(array_values($r));$msg='Draft copy created.';}
  elseif($action==='quick_post'){$id=(int)$_POST['id'];$field=(string)($_POST['field']??'');if($field==='breaking')db()->prepare("UPDATE news_posts SET is_breaking=1-is_breaking WHERE id=?")->execute([$id]);elseif($field==='featured')db()->prepare("UPDATE news_posts SET is_featured=1-is_featured WHERE id=?")->execute([$id]);elseif($field==='publish')db()->prepare("UPDATE news_posts SET status='published',published_at=COALESCE(published_at,NOW()) WHERE id=?")->execute([$id]);elseif($field==='draft')db()->prepare("UPDATE news_posts SET status='draft' WHERE id=?")->execute([$id]);$msg='Post updated.';}
