="datetime-local" name="published_at" value="<?=e(!empty($edit['published_at'])?date('Y-m-d\TH:i',strtotime((string)$edit['published_at'])):'')?>"></div></div><div class="news-editor-checks"><label><input type="checkbox" name="is_breaking" <?=($edit['is_breaking']??0)?'checked':''?>> Breaking News</label><label><input type="checkbox" name="is_featured" <?=($edit['is_featured']??0)?'checked':''?>> Featured Story</label></div><button class="btn">Save News Story</button></form></section><aside class="card news-editor-side"><h3>Publishing Guide</h3><div><b>English / Urdu</b><span>Use either language or publish a bilingual story.</span></div><div><b>Breaking</b><span>Breaking stories appear in the landing/news ticker widget.</span></div><div><b>Featured</b><span>Featured stories receive larger cards on the News Portal.</span></div><div><b>Video</b><span>Add a YouTube/Vimeo URL. ShahkotPK embeds known providers safely.</span></div><div><b>Scheduled</b><span>Choose Scheduled + a future publish time for automatic publication.</span></div><?php if($edit&&$edit['status']==='published'):?><a class="btn ghost" target="_blank" href="/news.php?slug=<?=urlencode((string)$edit['slug'])?>">View Public Story ↗</a><?php endif;?></aside></div><?php endif;?><?php require __DIR__.'/../app/end.php';?>
